#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/sha.h>

typedef struct {
    const unsigned char *ptr;
    int blocks;
} HASH_DESC;

/* 8-way */
extern void sha256_multi_block(void *ctx, HASH_DESC *desc, int num);

static void init_ctx(uint32_t ctx[8][8]) {
    static const uint32_t iv[8] = {
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
    };
    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 8; j++)
            ctx[i][j] = iv[j];
}

int main() {
    size_t nbytes = 20000 * 1024;
    // make divisible by 8*64
    size_t nblocks_total = nbytes / 64;
    size_t nb = (nblocks_total / 8) * 8; // blocks per stream * 8? 
    // each stream gets nb_each blocks
    int nb_each = (int)(nblocks_total / 8);
    size_t stream_bytes = (size_t)nb_each * 64;
    printf("nbytes=%zu nb_each=%d stream_bytes=%zu\n", nbytes, nb_each, stream_bytes);

    unsigned char *data = aligned_alloc(64, stream_bytes * 8 + 64);
    memset(data, 0x61, stream_bytes * 8);

    uint32_t ctx[8][8];
    // The asm does leaq 0x80(%rdi), %rdi then loads ymm from -0x80(%rdi) which is original rdi.
    // vmovdqu -0x80(%rdi) loads 32 bytes = state word 0 of all 8 lanes? 
    // Layout expected: for each of 8 state words, 8 lanes of uint32 interleaved? 
    // vmovdqu (%rdi) after rdi+=0x80 loads 32 bytes at offset 0x80.
    // There are 8 ymm loads at -0x80,-0x60,-0x40,-0x20,0,0x20,0x40,0x60 => 8*32 = 256 bytes.
    // So ctx is 256 bytes: 8 state words × 8 lanes × 4 bytes, lane-interleaved (AoS of words? or SoA).
    // ymm8 = first 32 bytes = 8 uint32 = likely state[0] for lanes 0..7 OR state words of lane0+...
    // Given later paddd with message words that were transposed across lanes, it's SoA:
    // ctx[word][lane]. Our init_ctx is ctx[lane][word] which is wrong. Let's try both.

    // Try layout A: uint32_t state[8 words][8 lanes]
    uint32_t state[8][8];
    for (int w = 0; w < 8; w++)
        for (int lane = 0; lane < 8; lane++)
            state[w][lane] = (uint32_t[]){0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}[w];

    HASH_DESC desc[8];
    for (int i = 0; i < 8; i++) {
        desc[i].ptr = data + i * stream_bytes;
        desc[i].blocks = nb_each;
    }

    sha256_multi_block(state, desc, 1); // num=? edx saved as 0x228(%rsp) which is the 3rd arg. Let's see usage.
    printf("after call state[0]: ");
    for (int lane = 0; lane < 8; lane++) printf("%08x ", state[0][lane]);
    printf("\n");

    // reference: hash first stream without padding (just compression) — not comparable directly.
    // Instead hash a known small input of exactly N blocks of zeros and compare intermediate.
    // Let's do 1 block of zeros and compare against a manual compression by hashing 64 zero bytes
    // with padding stripped... easier: use OpenSSL SHA256 on empty? no.
    // We'll implement check later.

    // Benchmark
    for (int w = 0; w < 8; w++)
        for (int lane = 0; lane < 8; lane++)
            state[w][lane] = 0x6a09e667;
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int r = 0; r < 20; r++) {
        for (int i = 0; i < 8; i++) { desc[i].ptr = data + i*stream_bytes; desc[i].blocks = nb_each; }
        sha256_multi_block(state, desc, 1);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    double mb = (double)stream_bytes * 8 * 20 / 1e6;
    printf("multi: %.3f s  %.1f MB/s\n", dt, mb/dt);

    unsigned char out[32];
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int r = 0; r < 20; r++) {
        SHA256(data, stream_bytes * 8, out);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    mb = (double)stream_bytes * 8 * 20 / 1e6;
    printf("SHA256: %.3f s  %.1f MB/s\n", dt, mb/dt);
    return 0;
}
EOF
