#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/sha.h>

typedef struct { const unsigned char *ptr; int blocks; } HASH_DESC;
extern void sha256_multi_block(void *ctx, HASH_DESC *desc, int num);

static const uint32_t IV[8] = {
    0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
    0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
};

/* Process one buffer with 8-way multi-block + scalar tail, producing a full SHA-256 digest. */
static void sha256_mb(const unsigned char *data, size_t len, unsigned char out[32]) {
    uint32_t state[8*8]; /* SoA: word-major, 8 lanes. 256 bytes, 32-aligned preferred */
    // align
    uint32_t *st = state;
    for (int w = 0; w < 8; w++)
        for (int lane = 0; lane < 8; lane++)
            st[w*8 + lane] = IV[w];

    size_t nblocks = len / 64;
    size_t full = nblocks / 8;          /* blocks each lane processes in the parallel section */
    size_t parallel_blocks = full * 8;  /* total blocks consumed in parallel */
    size_t tail = len - parallel_blocks * 64;

    if (full) {
        HASH_DESC desc[8];
        for (int lane = 0; lane < 8; lane++) {
            desc[lane].ptr = data + (size_t)lane * full * 64;
            desc[lane].blocks = (int)full;
        }
        sha256_multi_block(st, desc, 1);
    }

    /* Now we have 8 intermediate states, each over `full` blocks of disjoint regions.
       We need the hash of the concatenation. Multi-block can't chain different states
       into one. So this approach does NOT directly give a single hash!
       Instead, verify each lane equals independent compression of that slice. */
    printf("parallel blocks/lane=%zu tail=%zu\n", full, tail);
    for (int lane = 0; lane < 8; lane++) {
        printf("lane %d state0=%08x\n", lane, st[0*8 + lane]);
    }
}

/* Verify: compress `blocks` of data starting at ptr with IV using multi-block (1 lane used, others 0 blocks)
   vs a manual check. We'll just compare 8 independent hashes' compression states.
   Easiest correctness check: run multi-block on 8 copies and compare state words. */
int main() {
    size_t blocks = 1000;
    size_t bytes = blocks * 64;
    unsigned char *data = aligned_alloc(64, bytes * 8);
    for (size_t i = 0; i < bytes * 8; i++) data[i] = (unsigned char)(i * 131u + 7u);

    uint32_t st[64];
    for (int w = 0; w < 8; w++)
        for (int lane = 0; lane < 8; lane++)
            st[w*8 + lane] = IV[w];

    HASH_DESC desc[8];
    for (int lane = 0; lane < 8; lane++) {
        desc[lane].ptr = data + lane * bytes;
        desc[lane].blocks = (int)blocks;
    }
    sha256_multi_block(st, desc, 1);

    /* Reference: use SHA256 but we need raw compression. Implement via hashing
       data||padding and undoing final padding is hard.
       Instead call sha256_block_data_order directly. */
    extern void sha256_block_data_order(void *state, const void *data, size_t blocks);

    int ok = 1;
    for (int lane = 0; lane < 8; lane++) {
        uint32_t s[8];
        memcpy(s, IV, 32);
        sha256_block_data_order(s, data + lane * bytes, blocks);
        for (int w = 0; w < 8; w++) {
            if (s[w] != st[w*8 + lane]) {
                printf("MISMATCH lane %d word %d ref=%08x mb=%08x\n", lane, w, s[w], st[w*8+lane]);
                ok = 0;
                break;
            }
        }
    }
    printf(ok ? "MATCH\n" : "FAIL\n");

    /* speed on 20MB */
    size_t nbytes = 20000 * 1024;
    size_t nb = nbytes / 64;
    int each = (int)(nb / 8);
    size_t sb = (size_t)each * 64;
    unsigned char *big = aligned_alloc(64, sb * 8 + 256);
    memset(big, 0x61, sb * 8);

    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int r = 0; r < 10; r++) {
        for (int w = 0; w < 8; w++)
            for (int lane = 0; lane < 8; lane++)
                st[w*8+lane] = IV[w];
        for (int lane = 0; lane < 8; lane++) {
            desc[lane].ptr = big + lane * sb;
            desc[lane].blocks = each;
        }
        sha256_multi_block(st, desc, 1);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec-t0.tv_sec) + (t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("multi 8-lane: %.3f s  %.1f MB/s\n", dt, (double)sb*8*10/1e6/dt);

    unsigned char out[32];
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int r = 0; r < 10; r++) SHA256(big, sb*8, out);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    dt = (t1.tv_sec-t0.tv_sec) + (t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("SHA256:       %.3f s  %.1f MB/s\n", dt, (double)sb*8*10/1e6/dt);
    return 0;
}
EOF
