#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/sha.h>

extern void sha256_block_data_order(void *state, const void *data, size_t blocks);
extern void sha256_multi_block(void *ctx, void *desc, int num);

static const uint32_t IV[8] = {
    0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
    0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
};

int main() {
    size_t blocks = 4;
    size_t bytes = blocks * 64;
    unsigned char *data = aligned_alloc(64, bytes * 8);
    for (size_t i = 0; i < bytes*8; i++) data[i] = (unsigned char)(i*13+1);

    uint32_t ref[8][8];
    for (int lane = 0; lane < 8; lane++) {
        memcpy(ref[lane], IV, 32);
        sha256_block_data_order(ref[lane], data + lane*bytes, blocks);
    }
    printf("ref lane0 w0=%08x lane4 w0=%08x\n", ref[0][0], ref[4][0]);

    /* Try various desc strides. We'll pass a big zeroed buffer and place ptr/blocks at different offsets.
       From asm: lane0 ptr at (%rsi), blocks at 0x8(%rsi) as movl (so 4 bytes).
       lane1 ptr at 0x10, blocks at 0x18. That's 16-byte stride for first 4.
       lane4 ptr at 0x40, blocks at 0x48. Also 16-byte stride!
       So struct {ptr; int blocks;} with 8-byte padding IS 16 bytes. Why lanes 4-7 fail?
    */
    typedef struct { const unsigned char *ptr; int blocks; int pad; } D16;
    _Static_assert(sizeof(D16)==16, "sz");

    uint32_t st[64];
    D16 desc[8];
    for (int w = 0; w < 8; w++) for (int lane=0; lane<8; lane++) st[w*8+lane]=IV[w];
    for (int lane=0; lane<8; lane++) { desc[lane].ptr = data + lane*bytes; desc[lane].blocks = (int)blocks; desc[lane].pad=0; }
    sha256_multi_block(st, desc, 1);
    printf("layout SoA word-major:\n");
    for (int lane=0; lane<8; lane++) {
        int ok=1; for(int w=0;w<8;w++) if(st[w*8+lane]!=ref[lane][w]) ok=0;
        printf("  lane %d %s (got %08x ref %08x)\n", lane, ok?"OK":"BAD", st[0*8+lane], ref[lane][0]);
    }

    /* Maybe lanes 4-7 read from a different place because of the way ymm insert works and our data pointers
       are fine but state store uses different layout: first 4 lanes in low 128, next 4... 
       We already store SoA which should match ymm. Let's print all lane0 words. */
    printf("state dump word0 lanes: ");
    for (int lane=0; lane<8; lane++) printf("%08x ", st[lane]);
    printf("\n");

    /* Try num=8 */
    for (int w = 0; w < 8; w++) for (int lane=0; lane<8; lane++) st[w*8+lane]=IV[w];
    sha256_multi_block(st, desc, 8);
    printf("num=8 word0 lanes: ");
    for (int lane=0; lane<8; lane++) printf("%08x ", st[lane]);
    printf("\n");

    /* Maybe the function only does 4 lanes and the avx2 path we think is 8 is actually not selected?
       Check: our earlier disasm of the exported symbol jumps to shaext if bit 0x3d of OPENSSL_ia32cap, else avx if bit 28 of ecx.
       Bit 28 of ecx (leaf1) is AVX. So it jumps to sha256_multi_block_avx (the 4-lane SSE/AVX version), NOT avx2!
       The avx2 version is a separate local symbol never reached from the exported entry unless cap bits say so.
       Confirmed by results: only 4 lanes processed. So use 4-lane version. Let's verify 4 lanes match. */
    printf("4-lane check already visible above (lanes 0-3).\n");

    /* Confirm all 8 words of lanes 0-3 */
    int ok=1;
    for (int lane=0; lane<4; lane++) for (int w=0; w<8; w++) if (st[w*8+lane]!=ref[lane][w]) ok=0;
    /* st was overwritten by num=8 call. redo */
    for (int w = 0; w < 8; w++) for (int lane=0; lane<8; lane++) st[w*8+lane]=IV[w];
    sha256_multi_block(st, desc, 1);
    ok=1;
    for (int lane=0; lane<4; lane++) for (int w=0; w<8; w++) if (st[w*8+lane]!=ref[lane][w]) {ok=0; printf("bad lane %d w %d\n", lane, w);} 
    printf("lanes 0-3 full match: %s\n", ok?"YES":"NO");
    return 0;
}
EOF
