#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

extern void sha256_block_data_order(void *state, const void *data, size_t blocks);
extern void sha256_multi_block(void *ctx, void *desc, int num);

static const uint32_t IV[8] = {
    0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
    0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
};
typedef struct { const unsigned char *ptr; int blocks; int pad; } D16;

int main() {
    size_t blocks = 1000;
    size_t bytes = blocks * 64;
    unsigned char *data = aligned_alloc(64, bytes * 8 + 64);
    for (size_t i = 0; i < bytes*8; i++) data[i] = (unsigned char)(i*131u + (i>>8));

    uint32_t ref[8][8];
    for (int lane = 0; lane < 8; lane++) {
        memcpy(ref[lane], IV, 32);
        sha256_block_data_order(ref[lane], data + lane*bytes, blocks);
    }

    uint32_t st[64];
    D16 desc[8];
    for (int num = 1; num <= 16; num++) {
        for (int w = 0; w < 8; w++) for (int lane=0; lane<8; lane++) st[w*8+lane]=IV[w];
        for (int lane=0; lane<8; lane++) { desc[lane].ptr=data+lane*bytes; desc[lane].blocks=(int)blocks; desc[lane].pad=0; }
        sha256_multi_block(st, desc, num);
