        printf("num=%2d match=%s  w0:", num, ok?"YES":"no ");
        for (int lane=0; lane<8; lane++) printf(" %08x", st[lane]);
        printf("\n");
    }

    /* If num=8 matched, benchmark it */
    size_t nbytes = 20000*1024;
    int each = (int)((nbytes/64)/8);
    size_t sb = (size_t)each*64;
    unsigned char *big = aligned_alloc(64, sb*8+256);
    memset(big, 0x5a, sb*8);
    struct timespec t0,t1;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    for (int r=0;r<10;r++){
        for (int w=0;w<8;w++) for(int lane=0;lane<8;lane++) st[w*8+lane]=IV[w];
        for (int lane=0; lane<8; lane++){ desc[lane].ptr=big+lane*sb; desc[lane].blocks=each; }
        sha256_multi_block(st, desc, 8);
    }
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("num=8 throughput %.1f MB/s\n", (double)sb*8*10/1e6/dt);

