       sha256_multi_block at some addr, avx2 is local. We can dlsym the exported and add offset if we know it.
       From nm: _sha256_multi_block = 0x23f240, sha256_multi_block_avx2 = 0x2443a0, delta = 0x5160.
    */
    void *base = (void*)sha256_multi_block;
    void (*avx2)(void*, void*, int) = (void*)((char*)base + 0x5160);
    printf("base=%p avx2=%p\n", base, (void*)avx2);

    for (int w=0;w<8;w++) for(int lane=0;lane<8;lane++) st[w*8+lane]=IV[w];
    for (int lane=0; lane<8; lane++){ desc[lane].ptr=data+lane*bytes; desc[lane].blocks=(int)blocks; }
