        for (int lane=0; lane<8; lane++){ desc[lane].ptr=big+lane*sb; desc[lane].blocks=each; }
        avx2(st, desc, 1);
    }
    clock_gettime(CLOCK_MONOTONIC,&t1);
    dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
