#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/sha.h>

extern void sha256_block_data_order(void *state, const void *data, size_t blocks);
extern void sha256_multi_block(void *ctx, void *desc, int num);

static const uint32_t IV[8] = {
    0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
    0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
};
typedef struct { const unsigned char *ptr; int blocks; int pad; } D16;

/* Interleave 8 streams of `blocks` blocks each from src (contiguous per stream) into dst
   as 64-byte chunks round-robin: dst = blk0_s0, blk0_s1, ... blk0_s7, blk1_s0, ... */
static void interleave8(unsigned char *dst, const unsigned char *src, size_t blocks_each) {
    for (size_t b = 0; b < blocks_each; b++) {
        for (int s = 0; s < 8; s++) {
            memcpy(dst + (b*8 + s)*64, src + s*blocks_each*64 + b*64, 64);
        }
    }
}

int main() {
    size_t blocks = 500; /* per stream */
    size_t bytes = blocks * 64;
    unsigned char *src = aligned_alloc(64, bytes*8);
    unsigned char *dst = aligned_alloc(64, bytes*8);
    for (size_t i = 0; i < bytes*8; i++) src[i] = (unsigned char)(i*17+3);

    uint32_t ref[8][8];
    for (int s = 0; s < 8; s++) { memcpy(ref[s], IV, 32); sha256_block_data_order(ref[s], src + s*bytes, blocks); }

    interleave8(dst, src, blocks);

    /* Now point all 8 desc ptrs at dst+s*64 with the question: does the function advance by 64 or by 64*lanes?
       Test A: all ptrs at dst + lane*64, blocks=blocks. If it advances +64, streams collide.
       Test B: ptrs at dst + lane*64, but we need advance of 512. We'll just observe. */
    uint32_t st[64];
    D16 desc[8];
    for (int w=0; w<8; w++) for (int s=0;s<8;s++) st[w*8+s]=IV[w];
    for (int s=0; s<8; s++) { desc[s].ptr = dst + s*64; desc[s].blocks = (int)blocks; desc[s].pad=0; }
    sha256_multi_block(st, desc, 8);
    int ok=1;
    for (int s=0; s<8; s++) for (int w=0; w<8; w++) if (st[w*8+s]!=ref[s][w]) ok=0;
    printf("interleaved ptr+64*lane, blocks=%zu: %s\n", blocks, ok?"MATCH (advances 512)":"no");
    if (!ok) {
        for (int s=0; s<8; s++) printf("  s%d got %08x ref %08x\n", s, st[s], ref[s][0]);
    }

    /* If it advances by 64, then to hash 8 independent contiguous streams we already do that (no interleave).
       Interleave only helps if we want sequential memory for the single-hash case, which requires advance of 512
       (each lane skips the other lanes' blocks). Let's check advance amount by comparing against a constructed pattern.
    */

    /* Speed of interleave + multi vs plain SHA256 */
    size_t nbytes = 20000*1024;
    size_t nb = nbytes/64;
    int each = (int)(nb/8);
    size_t sb = (size_t)each*64;
    unsigned char *big = aligned_alloc(64, sb*8+256);
    unsigned char *iblk = aligned_alloc(64, sb*8+256);
    memset(big, 0x5a, sb*8);

    struct timespec t0,t1;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    for (int r=0;r<5;r++) interleave8(iblk, big, each);
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("interleave only: %.1f MB/s\n", (double)sb*8*5/1e6/dt);

    /* SIMD interleave speed using a simple 64-byte copy loop already measured.
       Try a version that copies 8*64 via larger chunks. */
    return 0;
}
