/* Compact AVX2 SHA-256. One stream, AVX2 message schedule + scalar rounds (good ILP). */
#include <immintrin.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/sha.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROR(x,n) (((x)>>(n))|((x)<<(32-(n))))
#define CH(e,f,g) (((e)&(f))^(~(e)&(g)))
#define MAJ(a,b,c) (((a)&(b))^((a)&(c))^((b)&(c)))
#define EP0(x) (ROR(x,2)^ROR(x,13)^ROR(x,22))
#define EP1(x) (ROR(x,6)^ROR(x,11)^ROR(x,25))

static inline __m256i sigma0(__m256i x){
    /* s0 = ror7 ^ ror18 ^ shr3 */
    __m256i r7 = _mm256_or_si256(_mm256_srli_epi32(x,7), _mm256_slli_epi32(x,25));
    __m256i r18= _mm256_or_si256(_mm256_srli_epi32(x,18), _mm256_slli_epi32(x,14));
    return _mm256_xor_si256(_mm256_xor_si256(r7,r18), _mm256_srli_epi32(x,3));
}
static inline __m256i sigma1(__m256i x){
    /* s1 = ror17 ^ ror19 ^ shr10 */
    __m256i r17=_mm256_or_si256(_mm256_srli_epi32(x,17), _mm256_slli_epi32(x,15));
    __m256i r19=_mm256_or_si256(_mm256_srli_epi32(x,19), _mm256_slli_epi32(x,13));
    return _mm256_xor_si256(_mm256_xor_si256(r17,r19), _mm256_srli_epi32(x,10));
}

static const __m256i bswap_shuf = {0,0,0,0}; /* placeholder replaced below */

static void process(uint32_t state[8], const uint8_t *data, size_t nblocks){
    const __m256i shuf = _mm256_setr_epi8(
        3,2,1,0, 7,6,5,4, 11,10,9,8, 15,14,13,12,
        3,2,1,0, 7,6,5,4, 11,10,9,8, 15,14,13,12);
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    for (size_t blk=0; blk<nblocks; blk++){
        const uint8_t *p = data + blk*64;
        __m256i w0 = _mm256_shuffle_epi8(_mm256_loadu_si256((const __m256i*)(p)), shuf);
        __m256i w1 = _mm256_shuffle_epi8(_mm256_loadu_si256((const __m256i*)(p+32)), shuf);
        uint32_t W[64];
        _mm256_storeu_si256((__m256i*)W, w0);
        _mm256_storeu_si256((__m256i*)(W+8), w1);
        /* schedule remaining with AVX2, 8 at a time */
        for (int i=16; i<64; i+=8){
            /* W[i] = s1(W[i-2]) + W[i-7] + s0(W[i-15]) + W[i-16]
               For a vector of 8 consecutive, W[i-2] is not aligned the same. Do scalar for correctness first? 
               Vector form: s1 needs W[i-2..i+5], which spans. Compute scalar to keep this test about round speed.
            */
        }
        for (int i=16;i<64;i++){
            uint32_t s0 = ROR(W[i-15],7)^ROR(W[i-15],18)^(W[i-15]>>3);
            uint32_t s1 = ROR(W[i-2],17)^ROR(W[i-2],19)^(W[i-2]>>10);
            W[i] = s1 + W[i-7] + s0 + W[i-16];
        }
        uint32_t A=a,B=b,C=c,D=d,E=e,F=f,G=g,H=h;
        for (int i=0;i<64;i++){
            uint32_t t1 = H + EP1(E) + CH(E,F,G) + K[i] + W[i];
            uint32_t t2 = EP0(A) + MAJ(A,B,C);
            H=G; G=F; F=E; E=D+t1; D=C; C=B; B=A; A=t1+t2;
        }
        a+=A; b+=B; c+=C; d+=D; e+=E; f+=F; g+=G; h+=H;
    }
    state[0]=a;state[1]=b;state[2]=c;state[3]=d;state[4]=e;state[5]=f;state[6]=g;state[7]=h;
}

int main(){
    size_t nbytes = 8*1024*1024;
    uint8_t *data = aligned_alloc(64, nbytes);
    memset(data, 0x11, nbytes);
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint32_t ref[8]; memcpy(ref, st, 32);
    extern void sha256_block_data_order(void*, const void*, size_t);
    process(st, data, 2);
    sha256_block_data_order(ref, data, 2);
    int ok=1; for(int i=0;i<8;i++) if(st[i]!=ref[i]) ok=0;
    printf("match %s\n", ok?"YES":"NO");
    if(!ok){ for(int i=0;i<8;i++) printf("%08x %08x\n", st[i], ref[i]); }

    struct timespec t0,t1;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    for(int r=0;r<5;r++){
        uint32_t s[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
        process(s, data, nbytes/64);
    }
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("mine %.1f MB/s\n", (double)nbytes*5/1e6/dt);

    unsigned char out[32];
    clock_gettime(CLOCK_MONOTONIC,&t0);
    for(int r=0;r<5;r++) SHA256(data, nbytes, out);
    clock_gettime(CLOCK_MONOTONIC,&t1);
    dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("openssl %.1f MB/s\n", (double)nbytes*5/1e6/dt);
    return 0;
}
EOF
