    for(int r=0;r<10;r++){
        for(int w=0;w<8;w++) for(int s=0;s<8;s++) st[w*8+s]=IV[w];
        for(int s=0;s<8;s++){ desc[s].ptr=big+s*sb; desc[s].blocks=each; }
