    const unsigned char *p; size_t blocks; uint32_t st[8];
    pthread_mutex_t m; pthread_cond_t cv;
    int go, stop, done;
} Worker;
static void *thr(void *arg){
    Worker *w=arg;
    pthread_mutex_lock(&w->m);
    for(;;){
        while(!w->go && !w->stop) pthread_cond_wait(&w->cv, &w->m);
        if(w->stop){ pthread_mutex_unlock(&w->m); return NULL; }
        w->go=0;
        pthread_mutex_unlock(&w->m);
        memcpy(w->st, IV, 32);
        sha256_block_data_order(w->st, w->p, w->blocks);
        pthread_mutex_lock(&w->m);
        w->done=1; pthread_cond_signal(&w->cv);
    }
}
