    for(int t=0;t<T;t++){
        memset(&ws[t],0,sizeof(ws[t]));
        pthread_mutex_init(&ws[t].m,NULL); pthread_cond_init(&ws[t].cv,NULL);
        size_t base=blocks/T; size_t b=(t==T-1)?blocks-base*(T-1):base;
        ws[t].p=data+t*base*64; ws[t].blocks=b;
        pthread_create(&th[t],NULL,thr,&ws[t]);
    }
    struct timespec t0,t1; clock_gettime(CLOCK_MONOTONIC,&t0);
    for(int r=0;r<8;r++){
        for(int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].m); ws[t].done=0; ws[t].go=1; pthread_cond_signal(&ws[t].cv); pthread_mutex_unlock(&ws[t].m); }
        for(int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].m); while(!ws[t].done) pthread_cond_wait(&ws[t].cv,&ws[t].m); pthread_mutex_unlock(&ws[t].m); }
    }
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("pool %d: %.1f MB/s  (%.4f s/iter)\n", T, (double)nbytes*8/1e6/dt, dt/8);
    for(int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].m); ws[t].stop=1; pthread_cond_signal(&ws[t].cv); pthread_mutex_unlock(&ws[t].m); }
    for(int t=0;t<T;t++) pthread_join(th[t],NULL);
    return 0;
}
