0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};

#define ROR(x,n) (((x)>>(n))|((x)<<(32-(n))))
#define CH(e,f,g) (((e)&(f))^((~(e))&(g)))
#define MAJ(a,b,c) (((a)&(b))^((a)&(c))^((b)&(c)))
#define EP0(x) (ROR(x,2)^ROR(x,13)^ROR(x,22))
#define EP1(x) (ROR(x,6)^ROR(x,11)^ROR(x,25))
#define S0(x) (ROR(x,7)^ROR(x,18)^((x)>>3))
#define S1(x) (ROR(x,17)^ROR(x,19)^((x)>>10))

/* Process two blocks (possibly from two streams) interleaved. */
static void two_blocks(uint32_t A0[8], const uint8_t *p0, uint32_t A1[8], const uint8_t *p1){
    uint32_t W0[64], W1[64];
    const __m256i shuf=_mm256_setr_epi8(3,2,1,0,7,6,5,4,11,10,9,8,15,14,13,12,3,2,1,0,7,6,5,4,11,10,9,8,15,14,13,12);
    __m256i a=_mm256_shuffle_epi8(_mm256_loadu_si256((const __m256i*)p0), shuf);
    __m256i b=_mm256_shuffle_epi8(_mm256_loadu_si256((const __m256i*)(p0+32)), shuf);
    _mm256_storeu_si256((__m256i*)W0, a);
    _mm256_storeu_si256((__m256i*)(W0+8), b);
    a=_mm256_shuffle_epi8(_mm256_loadu_si256((const __m256i*)p1), shuf);
    b=_mm256_shuffle_epi8(_mm256_loadu_si256((const __m256i*)(p1+32)), shuf);
    _mm256_storeu_si256((__m256i*)W1, a);
    _mm256_storeu_si256((__m256i*)(W1+8), b);
    for(int i=16;i<64;i++){
        W0[i]=S1(W0[i-2])+W0[i-7]+S0(W0[i-15])+W0[i-16];
        W1[i]=S1(W1[i-2])+W1[i-7]+S0(W1[i-15])+W1[i-16];
    }
    uint32_t a0=A0[0],b0=A0[1],c0=A0[2],d0=A0[3],e0=A0[4],f0=A0[5],g0=A0[6],h0=A0[7];
    uint32_t a1=A1[0],b1=A1[1],c1=A1[2],d1=A1[3],e1=A1[4],f1=A1[5],g1=A1[6],h1=A1[7];
    for(int i=0;i<64;i++){
        uint32_t t1=h0+EP1(e0)+CH(e0,f0,g0)+K[i]+W0[i];
        uint32_t t2=EP0(a0)+MAJ(a0,b0,c0);
        h0=g0; g0=f0; f0=e0; e0=d0+t1; d0=c0; c0=b0; b0=a0; a0=t1+t2;
        t1=h1+EP1(e1)+CH(e1,f1,g1)+K[i]+W1[i];
        t2=EP0(a1)+MAJ(a1,b1,c1);
        h1=g1; g1=f1; f1=e1; e1=d1+t1; d1=c1; c1=b1; b1=a1; a1=t1+t2;
    }
    A0[0]+=a0;A0[1]+=b0;A0[2]+=c0;A0[3]+=d0;A0[4]+=e0;A0[5]+=f0;A0[6]+=g0;A0[7]+=h0;
    A1[0]+=a1;A1[1]+=b1;A1[2]+=c1;A1[3]+=d1;A1[4]+=e1;A1[5]+=f1;A1[6]+=g1;A1[7]+=h1;
}

int main(){
    size_t n=8*1024*1024; uint8_t *d=aligned_alloc(64,n); memset(d,0x22,n);
    uint32_t s0[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint32_t s1[8]; memcpy(s1,s0,32);
    uint32_t r0[8]; memcpy(r0,s0,32); uint32_t r1[8]; memcpy(r1,s0,32);
    for(size_t i=0;i<4;i+=2) two_blocks(s0, d+i*64, s1, d+(i+1)*64);
    sha256_block_data_order(r0, d, 2); /* s0 processed blocks 0,2 -> not equal. just check block pair function on 2 blocks of one stream? skip correctness of pairing, check single by calling both ptrs same region sequentially. */
    /* correctness: process blocks 0 and 1 of two copies */
    memcpy(s0,r0,32); memcpy(s1,r0,32); /* reset to IV */
    memcpy(s0,(uint32_t[]){0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19},32);
    memcpy(s1,s0,32);
    two_blocks(s0, d, s1, d+64);
    uint32_t ref[8]; memcpy(ref,s0,32);
    memcpy(ref,(uint32_t[]){0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19},32);
    sha256_block_data_order(ref, d, 1);
