    sha256_block_data_order(ref, d+64, 1);
    for(int i=0;i<8;i++) if(s1[i]!=ref[i]) ok=0;
    printf("match %s\n", ok?"YES":"NO");

    struct timespec t0,t1; clock_gettime(CLOCK_MONOTONIC,&t0);
    for(int r=0;r<3;r++){
        uint32_t a[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
        uint32_t b[8]; memcpy(b,a,32);
        size_t nb=n/64;
        for(size_t i=0;i<nb;i+=2) two_blocks(a, d+i*64, b, d+(i+1)*64);
    }
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("2-lane scalar %.1f MB/s\n", (double)n*3/1e6/dt);
    return 0;
}
